// Automatic social media screenshot analysis (1.34). The screenshots in test/fixtures/screenshots are SYNTHETIC mock-ups
// labelled TEST FIXTURE (generated by scripts/make-screenshot-fixtures.mjs); they show no real accounts or events. Evidence
// and AI answers come from local TEST DOUBLES of Google Fact Check Tools and of the organisation's Ollama server.
import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { startServer, login } from "./helpers.js";
import { hashPassword } from "../server/lib/auth.js";
import { nowISO } from "../server/lib/db.js";
import { extractDocument } from "../server/lib/docs.js";
import { sniffImage, parseCount, extractPost, classifyLines, language } from "../server/lib/screenshot.js";

const FX = f => path.resolve("test/fixtures/screenshots", f);
let F, fake, S, ana, hod, view;
before(async () => {
  fake = http.createServer((req, res) => {
    const u = new URL(req.url, "http://x"), j = (c, o) => { res.writeHead(c, { "content-type": "application/json" }); res.end(JSON.stringify(o)); };
    if (u.pathname === "/v1alpha1/claims:search") { const q = u.searchParams.get("query") || "";
      return j(200, { claims: /ksh|pay|fee|m-?pesa/i.test(q) ? [{ text: "KDF recruits must pay a registration fee", claimant: "Facebook posts", claimReview: [{ publisher: { name: "PesaCheck" }, url: `${F}/factcheck/kdf-fee`, title: "TEST FIXTURE: No, KDF does not charge recruitment fees", textualRating: "False", reviewDate: "2026-10-20T00:00:00Z" }] }] : [] }); }
    if (u.pathname === "/factcheck/kdf-fee") { res.writeHead(200, { "content-type": "text/html" }); return res.end(`<html><head><title>TEST FIXTURE: No, KDF does not charge recruitment fees</title><meta property="article:published_time" content="2026-10-20T08:00:00Z"></head><body><article><h1>No, KDF does not charge recruitment fees</h1><p>TEST FIXTURE. Posts claim that applicants must pay KSh 2,000 registration fee through M-Pesa. The Kenya Defence Forces says recruitment is free of charge and no fee is paid at any stage.</p></article></body></html>`); }
    if (u.pathname === "/api/tags") return j(200, { models: [{ name: "qwen3:4b-instruct" }, { name: "qwen2.5vl:7b" }] });
    if (u.pathname === "/api/show") { let b = ""; req.on("data", d => (b += d)); req.on("end", () => { const m = JSON.parse(b || "{}").model; j(200, { capabilities: /vl/.test(m) ? ["completion", "vision"] : ["completion"] }); }); return; }
    if (u.pathname === "/api/chat") { let b = ""; req.on("data", d => (b += d)); req.on("end", () => {
      const body = JSON.parse(b), p = body.messages.at(-1).content, say = o => j(200, { model: "qwen3:4b-instruct", message: { content: typeof o === "string" ? o : JSON.stringify(o) } });
      // the text model must never be sent an image
      if (body.messages.some(m => m.images?.length)) { res.writeHead(400); return res.end("images sent to the text model"); }
      if (/single word OK/.test(p)) return say("OK");
      return say("{}"); }); return; }
    res.writeHead(404); res.end();
  });
  await new Promise(ok => fake.listen(0, "127.0.0.1", ok)); F = `http://127.0.0.1:${fake.address().port}`;
  S = await startServer({ allowPrivateFetch: false, search: { factcheckKey: "fc-key", factcheckBase: F, gdelt: false, wikipedia: false, timeoutMs: 3000 },
    ai: { provider: "ollama", model: "qwen3:4b-instruct", baseUrl: F, apiKey: "", timeoutMs: 8000, healthTimeoutMs: 4000, maxImages: 6 } });
  S.ctx.db.prepare("INSERT INTO users(username,display_name,role,designation,password_hash,created_at) VALUES (?,?,?,?,?,?)").run("hod", "HOD", "hod", "Head of Department, Information Operations", hashPassword("correct-horse-42"), nowISO());
  [ana, hod, view] = await Promise.all(["ana", "hod", "view"].map(u => login(S.base, u)));
});
after(async () => { await S.ctx.screenshots.idle(); await S.ctx.investigations.close(); await S.close(); fake.close(); });

const upload = (client, file, extra = {}) => { const fd = new FormData(); fd.append("file", new Blob([fs.readFileSync(FX(file))]), file); for (const [k, v] of Object.entries(extra)) fd.append(k, v); return client.post("/api/screenshots", undefined, { form: fd }); };
async function analyse(file, { client = ana, waitInvestigation = true } = {}) {
  const r = await upload(client, file); assert.equal(r.status, 202, JSON.stringify(r.body)); assert.match(r.body.id, /^SA-\d{6}$/);
  for (let i = 0; i < 1200; i++) {
    const g = (await client.get(`/api/screenshots/${r.body.id}`)).body;
    if (g.status === "failed") throw new Error(`screenshot analysis failed: ${g.error}`);
    if (g.status === "done" && (!waitInvestigation || ["done", "failed"].includes(g.investigation?.status))) return g;
    await new Promise(ok => setTimeout(ok, 100));
  }
  throw new Error("screenshot analysis did not finish");
}
const V = f => f?.value ?? null;

test("unit: formats are checked by content; counts, line types and language are read without guessing", () => {
  assert.equal(sniffImage(fs.readFileSync(FX("facebook-post.png"))), "png"); assert.equal(sniffImage(fs.readFileSync(FX("x-post.webp"))), "webp");
  assert.equal(sniffImage(Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0, 0, 0, 0, 0, 0, 0, 0])), "jpeg"); assert.equal(sniffImage(fs.readFileSync(FX("not-an-image.png"))), null);
  assert.deepEqual(parseCount("1.2K"), { value: 1200, approximate: true }); assert.deepEqual(parseCount("1,234"), { value: 1234, approximate: false }); assert.equal(parseCount("abc"), null);
  const L = classifyLines([{ text: "Kenya Daily Updates", conf: 95 }, { text: "2h - Public", conf: 90 }, { text: "1.2K reactions 345 comments - 89 shares", conf: 90 }, { text: "Like Comment Share", conf: 96 }, { text: "Sponsored", conf: 90 }, { text: "&- F4 N", conf: 55 }]);
  assert.deepEqual(L.map(x => x.type), ["name", "time", "metric", "action", "ad", "noise"]);
  assert.equal(language("Wanajeshi wa KDF wako katika eneo hili na watu wanasema kwamba hali ni salama").code, "sw");
  // a text alone: everything that is not shown stays "not available", never invented
  const x = extractPost({ lines: [{ text: "TEST FIXTURE: The army opened a new hospital in Wajir.", conf: 95 }], width: 600, height: 100 });
  for (const k of ["account", "published_at", "platform", "urls", "hashtags"]) assert.equal(x[k].basis, "not_available", k);
  assert.ok(Object.values(x.engagement).every(e => e.value === null && e.basis === "not_available"));
});

test("Facebook screenshot: platform, page, time, text, hashtags, mention, engagement and picture; comments excluded; fields populated; automatic investigation, four-section one-page draft and automatic HOD submission", async () => {
  const s = await analyse("facebook-post.png"), x = s.extraction, f = s.form;
  assert.equal(V(x.platform), "Facebook"); assert.equal(x.platform.basis, "inferred");
  assert.equal(V(x.account), "Kenya Daily Updates"); assert.equal(x.account.basis, "observed");
  assert.equal(V(x.posted_text), "2h · Public"); assert.equal(x.published_at.basis, "not_available", "a relative time is not turned into an invented date");
  assert.match(V(x.text), /KDF recruitment is now open\. Applicants must pay KSh 2,000 registration fee through M-Pesa before Friday\./);
  assert.doesNotMatch(V(x.text), /Is this true|looks like a scam|Most relevant|Like Comment Share|reactions/, "comments, interface text and counts are not post text");
  assert.deepEqual(V(x.hashtags), ["#KDFRecruitment"]); assert.deepEqual(V(x.mentions), ["@KDFInfo"]); assert.equal(V(x.urls), null);
  assert.equal(V(x.engagement.reactions), 1200); assert.match(x.engagement.reactions.note, /approximate/); assert.equal(V(x.engagement.comments), 345); assert.equal(V(x.engagement.shares), 89);
  assert.equal(x.media.count, 1, "the photo region is found"); assert.equal(x.comments.length, 2); assert.equal(x.comments_excluded, 2);
  assert.equal(x.kdf_relevance.relevant, true); assert.equal(V(x.language), "English");
  assert.ok(x.uncertainties.some(u => /not proof/.test(u)));
  // populated Social Media Analysis fields
  assert.match(V(f.name), /Facebook screenshot/); assert.match(V(f.source), /Screenshot submitted by ANA.*apparent platform: Facebook.*account shown: Kenya Daily Updates/);
  assert.equal(V(f.authorisation), "Submitted by the analyst for analysis in AIVS. No platform API access, permission or consent is recorded for this content.");
  assert.match(V(f.research_question), /^Is the claim that .+ accurate/); assert.match(V(f.description), /Not available: link to the original/); assert.match(V(f.description), /Excluded: 2 comment/);
  assert.equal(f.post_record.saved, false); assert.match(f.post_record.reason, /no exact publication time/);
  const ds = S.ctx.db.prepare("SELECT * FROM io_datasets WHERE id = ?").get(s.dataset_id);
  assert.equal(ds.name, V(f.name)); assert.equal(ds.authorisation, V(f.authorisation)); assert.equal(ds.collection_method, "screenshot (automatic extraction)"); assert.equal(ds.posts, 0);
  // the pre-stages and the investigation
  assert.ok(s.stages.every(st => ["done", "warning", "skipped"].includes(st.status)), JSON.stringify(s.stages));
  assert.equal(s.stages.find(st => st.key === "original").status, "skipped"); assert.match(s.stages.find(st => st.key === "vision").detail, /No image model is configured.*not used for images/);
  const inv = s.investigation; assert.equal(inv.status, "done", inv.error);
  assert.ok(inv.result.claims.length >= 1 && inv.result.claims.length <= 2, "at most two principal claims");
  assert.equal(inv.result.verdict, "contradicted", "the fact-check contradicts the fee claim");
  const full = (await ana.get(`/api/investigations/${inv.id}`)).body.result;
  assert.equal(full.source.input_type, "screenshot"); assert.equal(full.source.platform, "Facebook"); assert.equal(full.source.account, "Kenya Daily Updates");
  assert.ok(!full.evidence.some(e => /screenshot/i.test(e.connector || "") || e.url?.includes("/api/screenshots")), "the screenshot is never evidence");
  assert.ok((await ana.get(`/api/cases/${full.case_id}`)).body.case.uncertainties.includes("not independently retrieved"), "uncertainty recorded");
  const a = (await ana.get(`/api/investigations/${inv.id}/report.json`)).body;
  assert.match(a.header.source, /^Screenshot · Facebook \(apparent\) · Kenya Daily Updates/); assert.match(a.background, /not independently retrieved/);
  assert.ok(a.recommendations.length >= 3 && a.recommendations.length <= 5 && a.recommendations.every(r => r.startsWith("There is a need to")));
  const html = (await ana.get(`/api/investigations/${inv.id}/report.html`)).body; assert.equal((html.match(/<h2>/g) || []).length, 4); assert.match(html, /DRAFT — NOT APPROVED/);
  const pdf = Buffer.from(await (await fetch(`${S.base}/api/investigations/${inv.id}/report.pdf`, { headers: { cookie: ana.cookie } })).arrayBuffer()), d = await extractDocument(pdf, "r.pdf");
  assert.equal((pdf.toString("latin1").match(/\/Type \/Page\b/g) || []).length, 1, "one A4 page"); assert.match(d.text.replace(/\s+/g, " "), /DRAFT - NOT APPROVED/);
  // submitted automatically to the HOD; nothing is approved until the HOD decides
  assert.equal(s.approval.status, "pending"); assert.equal(s.approval.assigned, "HOD");
  assert.ok(JSON.stringify((await hod.get("/api/approvals")).body).includes(inv.id), "the HOD sees it in the approval queue");
  assert.doesNotMatch(html, /APPROVED BY HEAD OF DEPARTMENT/);
});

test("Instagram screenshot: account from the header, caption without the repeated account name, 'Liked by' as an inferred lower bound, relative time", async () => {
  const x = (await analyse("instagram-post.png", { waitInvestigation: false })).extraction;
  assert.equal(V(x.platform), "Instagram"); assert.equal(V(x.account), "kdf_news_ke"); assert.equal(V(x.posted_text), "2 hours ago"); assert.equal(x.published_at.basis, "not_available");
  assert.match(V(x.text), /^TEST FI.TURE: Soldiers deployed to Lamu County today/); assert.doesNotMatch(V(x.text), /^kdf/i);
  assert.deepEqual(V(x.hashtags), ["#KDF", "#Lamu"]); assert.equal(V(x.engagement.likes), 1235); assert.equal(x.engagement.likes.basis, "inferred"); assert.equal(V(x.engagement.comments), 56);
  assert.equal(x.media.count, 1);
});

test("X screenshot: display name and handle, exact date and time, link visible but not retrievable, engagement, reply excluded; the post is saved as a dataset row", async () => {
  const s = await analyse("x-post.png"), x = s.extraction;
  assert.equal(V(x.platform), "X (Twitter)"); assert.equal(V(x.account), "Defence Watch KE (@defwatch_ke)"); assert.equal(V(x.handle), "@defwatch_ke");
  assert.equal(V(x.published_at), "2026-10-27T09:45:00.000Z"); assert.equal(x.published_at.basis, "observed"); assert.match(x.published_at.note, /East Africa Time/);
  assert.deepEqual(V(x.urls), ["https://example.test/kdf-pass-out"]);
  assert.deepEqual({ likes: V(x.engagement.likes), reposts: V(x.engagement.reposts), quotes: V(x.engagement.quotes), views: V(x.engagement.views), bookmarks: V(x.engagement.bookmarks) }, { likes: 450, reposts: 12, quotes: 3, views: 3456, bookmarks: 8 });
  assert.equal(x.comments.length, 1); assert.match(x.comments[0].author, /@amina_h/); assert.doesNotMatch(V(x.text), /Congratulations/);
  assert.equal(x.original.attempted, true); assert.equal(x.original.retrieved, false, "the visible link is tried, its failure recorded"); assert.ok(x.original.reason);
  assert.equal(s.stages.find(st => st.key === "original").status, "warning");
  assert.equal(s.form.post_record.saved, true);
  const p = S.ctx.db.prepare("SELECT * FROM io_posts WHERE dataset_id = ?").all(s.dataset_id);
  assert.equal(p.length, 1); assert.equal(p[0].account, "defwatch_ke"); assert.equal(p[0].posted_at, "2026-10-27T09:45:00.000Z"); assert.equal(p[0].likes, 450); assert.match(p[0].collected_via, /screenshot SA-/);
  const full = (await ana.get(`/api/investigations/${s.investigation.id}`)).body.result;
  assert.equal(full.source.published_at, "2026-10-27T09:45:00.000Z"); assert.equal(full.source.url, "https://example.test/kdf-pass-out");
  assert.ok(s.investigation.result.claims.length <= 2);
  assert.ok(["insufficient", "not_verifiable", "mixed"].includes(s.investigation.result.verdict), `nothing supports it, so it is not Supported (${s.investigation.result.verdict})`);
});

test("image-and-text, incomplete metadata and multiple posts", async () => {
  const a = (await analyse("x-post-image.png", { waitInvestigation: false })).extraction;
  assert.equal(V(a.account), "Coast Alerts (@coast_alerts)"); assert.equal(V(a.posted_text), "3h"); assert.equal(a.media.count, 1);
  assert.equal(V(a.text), "TEST FIXTURE: Photo shows KDF trucks carrying relief food to flood victims in Garissa this morning.", "OCR noise from the photo is left out");
  const b = await analyse("incomplete-metadata.png"), y = b.extraction;
  assert.match(V(y.text), /Kenya Army has closed the Nairobi to Mombasa highway/);
  for (const k of ["platform", "account", "posted_text", "published_at", "urls"]) assert.equal(y[k].basis, "not_available", k);
  assert.deepEqual(y.not_shown, ["account", "date/time", "engagement figures", "link to the original", "embedded picture"]);
  assert.match(V(b.form.name), /Screenshot \(platform not identified\)/); assert.match(V(b.form.source), /platform not identified; account not visible/);
  assert.equal(b.investigation.status, "done", "missing metadata does not block the investigation");
  const c = (await analyse("multiple-posts.png", { waitInvestigation: false })).extraction;
  assert.equal(c.multiple_posts, true); assert.equal(c.posts.length, 3); assert.equal(c.advertisements_excluded, 1); assert.equal(c.posts.find(p => p.main).index, 1);
  assert.equal(V(c.account), "Nairobi Buzz"); assert.match(V(c.text), /free medical camps in Isiolo/); assert.doesNotMatch(V(c.text), /discounts|Eldoret/);
  assert.ok(c.uncertainties.some(u => /could not be read reliably/.test(u)), "the misread time is reported, not guessed");
});

test("WebP accepted; duplicates recognised; unsupported formats refused clearly; permissions; corrections recorded; capabilities checked, not assumed", async () => {
  const w = await upload(ana, "x-post.webp"); assert.equal(w.status, 202);
  const again = await upload(ana, "facebook-post.png"); assert.equal(again.status, 200); assert.equal(again.body.duplicate, true); assert.ok(again.body.investigation_id);
  const bad = await upload(ana, "not-an-image.png"); assert.equal(bad.status, 415); assert.match(bad.body.error, /GIF image.*PNG, JPEG or WebP/);
  assert.equal((await upload(view, "x-post.png")).status, 403);
  const id = again.body.id;
  const e = await ana.patch(`/api/screenshots/${id}`, { research_question: "TEST FIXTURE: Is KDF recruitment free of charge?" });
  assert.equal(e.status, 200); assert.equal(e.body.form.research_question.basis, "analyst"); assert.equal(e.body.form_edits.length, 1); assert.match(e.body.form_edits[0].from, /^Is the claim that/);
  assert.equal(S.ctx.db.prepare("SELECT research_question FROM io_datasets WHERE id = ?").get(e.body.dataset_id).research_question, "TEST FIXTURE: Is KDF recruitment free of charge?");
  const img = await fetch(`${S.base}/api/screenshots/${id}/image`, { headers: { cookie: ana.cookie } }); assert.equal(img.headers.get("content-type"), "image/png"); assert.match(img.headers.get("content-security-policy"), /sandbox/);
  const list = (await ana.get("/api/screenshots")).body.analyses; assert.ok(list.length >= 6 && list.some(l => l.platform === "Instagram"));
  const cap = (await ana.get("/api/screenshots/capabilities?fresh=1")).body;
  assert.equal(cap.ocr.installed, true); assert.deepEqual(cap.ocr.languages, ["eng", "swa"]); assert.equal(cap.text_model.images, false);
  assert.equal(cap.vision.configured, null); assert.equal(cap.vision.supported, false, "no image model is assumed");
  assert.deepEqual(cap.vision.installed_vision_models, ["qwen2.5vl:7b"], "the server's models are checked for the vision capability");
  assert.ok(cap.models.find(m => m.name === "qwen3:4b-instruct").vision === false);
  // the second upload (WebP) finishes too
  for (let i = 0; i < 600; i++) { const g = (await ana.get(`/api/screenshots/${w.body.id}`)).body; if (g.status === "done") { assert.equal(g.extraction.handle.value, "@defwatch_ke"); assert.ok(g.extraction.duplicates.length >= 1, "near-duplicate content found"); break; } if (g.status === "failed") assert.fail(g.error); await new Promise(ok => setTimeout(ok, 100)); }
});
